// reactstrap components
import {
    Button,
    Card,
    CardHeader,
    CardBody,
    FormGroup,
    Form,
    Input,
    Container,
    Row,
    Col,
    Label,
  } from "reactstrap";
  import { useState } from "react";
  import AIHelper from "components/AIHelper"; // Placeholder for AI suggestions

  const CarbonDataInput = () => {
    const [carbonData, setCarbonData] = useState({
      date: "",
      category: "",
      value: "",
      unit: "",
    });
    const [carbonImpact, setCarbonImpact] = useState(0);
    const [badge, setBadge] = useState("");

    const handleChange = (e) => {
      setCarbonData({ ...carbonData, [e.target.name]: e.target.value });
    };

    const calculateImpact = () => {
      // Dummy calculation logic (replace with actual formula)
      const impact = parseFloat(carbonData.value) * 0.5;
      setCarbonImpact(impact);

      // Assigning badges based on impact reduction
      if (impact < 20) setBadge("Eco Starter");
      else if (impact < 50) setBadge("Green Warrior");
      else setBadge("Carbon Master");
    };

    return (
      <Container className="mt--7" fluid>
        <Row>
          <Col className="order-xl-1" xl="8">
            <Card className="bg-secondary shadow">
              <CardHeader className="bg-white border-0">
                <h3 className="mb-0">Carbon Footprint Data Input</h3>
              </CardHeader>
              <CardBody>
                <Form>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <Label>Date</Label>
                        <Input
                          type="date"
                          name="date"
                          value={carbonData.date}
                          onChange={handleChange}
                        />
                      </FormGroup>
                    </Col>
                  </Row>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <Label>Activity Category</Label>
                        <Input
                          type="select"
                          name="category"
                          value={carbonData.category}
                          onChange={handleChange}
                        >
                          <option value="">Select Category</option>
                          <option value="Transport">Transport</option>
                          <option value="Electricity">Electricity</option>
                          <option value="Diet">Diet</option>
                          <option value="Waste">Waste Management</option>
                        </Input>
                      </FormGroup>
                    </Col>
                    <Col lg="6">
                      <FormGroup>
                        <Label>Value</Label>
                        <Input
                          type="number"
                          name="value"
                          placeholder="Enter amount"
                          value={carbonData.value}
                          onChange={handleChange}
                        />
                      </FormGroup>
                    </Col>
                  </Row>
                  <Row>
                    <Col lg="6">
                      <FormGroup>
                        <Label>Unit</Label>
                        <Input
                          type="select"
                          name="unit"
                          value={carbonData.unit}
                          onChange={handleChange}
                        >
                          <option value="kg">kg CO2</option>
                          <option value="liters">Liters</option>
                          <option value="kWh">kWh</option>
                        </Input>
                      </FormGroup>
                    </Col>
                  </Row>
                  <Row>
                    <Col lg="6">
                      <Button color="primary" onClick={calculateImpact}>
                        Calculate Impact
                      </Button>
                    </Col>
                  </Row>
                  <Row className="mt-3">
                    <Col lg="6">
                      <h4>Estimated Carbon Impact: {carbonImpact} kg CO2</h4>
                      {badge && <h5>Achievement: {badge}</h5>}
                    </Col>
                  </Row>
                </Form>
                <AIHelper category={carbonData.category} value={carbonData.value} />
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    );
  };

  export default CarbonDataInput;
